            elif "nodes" in inst and isinstance(inst["nodes"], (list, tuple)):
                ids = list(inst["nodes"])
            else:
                coords = get_coords(inst)
                demands = get_demands(inst)
                if isinstance(coords, dict):
                    ids = list(coords.keys())
                elif isinstance(coords, (list, tuple)):
                    ids = list(range(len(coords)))
                elif isinstance(demands, dict):
                    ids = list(demands.keys())
                elif isinstance(demands, (list, tuple)):
                    ids = list(range(len(demands)))
        return [i for i in ids if i != depot]

    def demand_of(node, demands):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(node, 1)
        try:
            return demands[node]
        except Exception:
            return 1

    def coord_of(node, coords):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(node, None)
        try:
            return coords[node]
        except Exception:
            return None

    def dist(a, b, coords):
        pa = coord_of(a, coords)
        pb = coord_of(b, coords)
        if pa is None or pb is None:
            return 0
        ax, ay = pa[0], pa[1]
        bx, by = pb[0], pb[1]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    def route_load(route, demands):
        s = 0
        for n in route:
            s += demand_of(n, demands)
        return s

    def route_cost(route, depot, coords):
        if not route:
            return 0
        c = dist(depot, route[0], coords) + dist(route[-1], depot, coords)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1], coords)
        return c

    depot = get_depot(instance)
    capacity = get_capacity(instance)
    coords = get_coords(instance)
    demands = get_demands(instance)
    customers = all_customer_ids(instance, depot)

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c, demands)
        capacity = max(1, total)

    if not customers:
        return []

    # Deterministic customer ordering: sweep if coordinates exist, else by id.
    if coords is not None:
        dpt = coord_of(depot, coords)
        if dpt is None:
            dpt = (0, 0)
        dx0, dy0 = dpt[0], dpt[1]

        def key_fn(c):
            p = coord_of(c, coords)
            if p is None:
                return (0, 0, c)
            dx = p[0] - dx0
            dy = p[1] - dy0
            ang = dy if dx == 0 and dy == 0 else (dy / (abs(dx) + abs(dy) + 1e-12))
            return (ang, dist(depot, c, coords), demand_of(c, demands), c)

        ordered = sorted(customers, key=key_fn)
    else:
        ordered = sorted(customers, key=lambda c: (demand_of(c, demands), c))

    unserved = set(ordered)
    routes = []

    # Constructive phase: angle/sweep ordering with best-feasible append.
    while unserved:
        route = []
        load = 0
        current = depot

        # choose best starter
        starter = None
        starter_key = None
        for c in ordered:
            if c not in unserved:
                continue
            d = demand_of(c, demands)
            if d <= capacity and load + d <= capacity:
                k = (dist(depot, c, coords), d, c)
                if starter_key is None or k < starter_key:
                    starter_key = k
                    starter = c
        if starter is None:
            starter = min(unserved, key=lambda c: (demand_of(c, demands), dist(depot, c, coords), c))

        route.append(starter)
        load += demand_of(starter, demands)
        unserved.remove(starter)
        current = starter

        while True:
            best = None
            best_key = None
            for c in unserved:
                d = demand_of(c, demands)
                if load + d > capacity:
                    continue
                # nearest neighbor with slight preference to low-demand
                k = (dist(current, c, coords), dist(depot, c, coords), d, c)
                if best_key is None or k < best_key:
                    best_key = k
                    best = c
            if best is None:
                break
            route.append(best)
            load += demand_of(best, demands)
            unserved.remove(best)
            current = best

        routes.append(route)

    # Repair: if any route is over capacity, split it greedily.
    repaired = []
    for r in routes:
        cur = []
        load = 0
        for c in r:
            d = demand_of(c, demands)
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [c]
                load = d
            else:
                cur.append(c)
                load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    # Local search: 2-opt inside routes.
    def two_opt(route):
        if len(route) < 4:
            return route
        best = route[:]
        best_cost = route_cost(best, depot, coords)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cst = route_cost(cand, depot, coords)
                    if cst + 1e-12 < best_cost:
                        best = cand
                        best_cost = cst
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes]

    # Local search: relocate customers between routes when feasible and beneficial.
    improved = True
    while improved:
        improved = False
        best_move = None
        best_delta = 0

        for i in range(len(routes)):
            ri = routes[i]
            li = route_load(ri, demands)
            for pos in range(len(ri)):
                c = ri[pos]
                dc = demand_of(c, demands)
                ri_wo = ri[:pos] + ri[pos + 1:]
                old_i = route_cost(ri, depot, coords)
                new_i = route_cost(ri_wo, depot, coords)

                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj, demands)
                    if lj + dc > capacity:
                        continue
                    old_j = route_cost(rj, depot, coords)
                    for ins in range(len(rj) + 1):
                        cand_j = rj[:ins] + [c] + rj[ins:]
                        new_j = route_cost(cand_j, depot, coords)
                        delta = (new_i + new_j) - (old_i + old_j)
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_move = (i, j, pos, ins)

        if best_move is not None:
            i, j, pos, ins = best_move
            c = routes[i][pos]
            routes[i] = routes[i][:pos] + routes[i][pos + 1:]
            routes[j] = routes[j][:ins] + [c] + routes[j][ins:]
            if not routes[i]:
                routes.pop(i)
            routes = [two_opt(r) for r in routes]
            improved = True

    # Remove any empty routes and ensure every customer appears once.
    seen = set()
    final_routes = []
    for r in routes:
        rr = []
        load = 0
        for c in r:
            if c in seen:
                continue
            seen.add(c)
            rr.append(c)
            load += demand_of(c, demands)
        if rr:
            final_routes.append(rr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        d = demand_of(c, demands)
        best_j = None
        best_pos = None
        best_cost = None
        for j in range(len(final_routes)):
            if route_load(final_routes[j], demands) + d > capacity:
                continue
            for pos in range(len(final_routes[j]) + 1):
                cand = final_routes[j][:pos] + [c] + final_routes[j][pos:]
                cost = route_cost(cand, depot, coords)
                if best_cost is None or cost < best_cost:
                    best_cost = cost
                    best_j = j
                    best_pos = pos
                    placed = True
        if placed:
            final_routes[best_j] = final_routes[best_j][:best_pos] + [c] + final_routes[best_j][best_pos:]
        else:
            final_routes.append([c])

    # Final deduplication safeguard while keeping order.
    seen = set()
    cleaned = []
    for r in final_routes:
        rr = []
        for c in r:
            if c not in seen:
                seen.add(c)
                rr.append(c)
        if rr:
            cleaned.append(rr)

    return cleaned
